sys_script_include.script:
var MediaUtils = Class.create();
MediaUtils.prototype = {
    initialize: function() {},
    refQualMedias: function() {
        var moviesToBeShown = [];
        var grMedias  = new GlideRecord("x_1270470_netflix_media");
        grMedias.addQuery("state", "3");
        grMedias.query();

        while(grMedias.next()){
            var grReview = new GlideRecord("x_1270470_netflix_review");
            // grReview.addQuery("opened_by", "me");
            // grReview.addQuery("state", "3");
            //grReview.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4")
            grReview.addQuery("opened_by", gs.getUserID());
            grReview.addQuery("title", grMedias.sys_id);
            grReview.addQuery("state", "!=", "4");
            grReview.query();
            if(!grReview.next()){
                moviesToBeShown.push(grMedias.getUniqueValue());
            }
        }
        return moviesToBeShown;
    },

    type: 'MediaUtils'
};
